def terms_of(stored: str) -> list[str]:
    """One clause per line; a blank setting falls back to the standard terms."""
    lines = [l.strip() for l in (stored or "").splitlines() if l.strip()]
    return lines or DEFAULT_QUOTATION_TERMS
